using Amazon.S3;using Amazon.S3.Model;using System.Net.Sockets;using System.Buffers.Binary;using Microsoft.EntityFrameworkCore;using MailKit.Net.Smtp;using MimeKit;using System.Diagnostics;
namespace Decont;
public interface IStore {Task Put(string key,byte[] bytes,string mime,CancellationToken ct=default);Task<byte[]> Get(string key,CancellationToken ct=default);}
public class LocalStore(IConfiguration config):IStore {string Root=>config["Storage:Directory"]??Path.Combine(Directory.GetCurrentDirectory(),".data","objects");string PathOf(string key){Guard.Require(key.Split('/').All(p=>p.Length>0&&!p.Contains("..")&&p.All(c=>char.IsAsciiLetterOrDigit(c)||c is '-' or '_' or '.')),"storage_key","Cheie invalidă.","Invalid storage key.");return Path.Combine(Root,key);}
 public async Task Put(string key,byte[] bytes,string mime,CancellationToken ct=default){var path=PathOf(key);Directory.CreateDirectory(Path.GetDirectoryName(path)!);await using var file=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None);await file.WriteAsync(bytes,ct);}
 public Task<byte[]> Get(string key,CancellationToken ct=default)=>File.ReadAllBytesAsync(PathOf(key),ct);
}
public class S3Store(IAmazonS3 s3,IConfiguration config):IStore {string Bucket=>config["Storage:Bucket"]??throw new InvalidOperationException("Bucket missing");public async Task Put(string key,byte[] bytes,string mime,CancellationToken ct=default)=>await s3.PutObjectAsync(new(){BucketName=Bucket,Key=key,ContentType=mime,InputStream=new MemoryStream(bytes)},ct);public async Task<byte[]> Get(string key,CancellationToken ct=default){using var result=await s3.GetObjectAsync(Bucket,key,ct);using var ms=new MemoryStream();await result.ResponseStream.CopyToAsync(ms,ct);return ms.ToArray();}}
public static class Files {public const long MaxFile=25*1024*1024,MaxReport=200*1024*1024;public static string Mime(byte[] b,string name){var ext=Path.GetExtension(name).ToLowerInvariant();if(ext==".pdf"&&b.Length>=5&&b.AsSpan(0,5).SequenceEqual("%PDF-"u8))return "application/pdf";if(ext==".png"&&b.Length>=8&&b.AsSpan(0,8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}))return "image/png";if(ext is ".jpg" or ".jpeg"&&b.Length>=3&&b[0]==255&&b[1]==216&&b[2]==255)return "image/jpeg";if(ext is ".heic" or ".heif"&&b.Length>=12&&b.AsSpan(4,4).SequenceEqual("ftyp"u8)&&new[]{"heic","heix","hevc","hevx","mif1"}.Contains(System.Text.Encoding.ASCII.GetString(b,8,4)))return "image/heic";throw new DomainException("file_type","Fișier PDF, JPG, PNG sau HEIC valid necesar.","A valid PDF, JPG, PNG or HEIC file is required.");}}
public class Worker(IServiceScopeFactory scopes,IConfiguration config,ILogger<Worker> log):BackgroundService {
 protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){try{using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();var now=DateTime.UtcNow;var candidate=await db.Jobs.Where(j=>(j.State=="Pending"||j.State=="Processing")&&j.Due<=now).OrderBy(j=>j.Due).FirstOrDefaultAsync(ct);if(candidate==null){await Task.Delay(1500,ct);continue;}var claim=await db.Jobs.Where(j=>j.Id==candidate.Id&&j.Due<=now&&(j.State=="Pending"||j.State=="Processing")).ExecuteUpdateAsync(s=>s.SetProperty(j=>j.State,"Processing").SetProperty(j=>j.Due,now.AddMinutes(5)).SetProperty(j=>j.Attempts,j=>j.Attempts+1),ct);if(claim==0)continue;db.Entry(candidate).State=EntityState.Detached;var job=await db.Jobs.SingleAsync(j=>j.Id==candidate.Id,ct);try{await Process(job,db,scope.ServiceProvider.GetRequiredService<IStore>(),ct);job.State="Completed";job.Error=null;}catch(Exception ex)when(!ct.IsCancellationRequested){log.LogError(ex,"Job {Id} failed",job.Id);job.State=job.Attempts>=5?"Failed":"Pending";job.Error="Processing failed; see server logs.";job.Due=DateTime.UtcNow.AddMinutes(Math.Pow(2,job.Attempts));}await db.SaveChangesAsync(ct);}catch(OperationCanceledException)when(ct.IsCancellationRequested){break;}catch(Exception ex){log.LogError(ex,"Worker polling failed");await Task.Delay(3000,ct);}}}
 async Task Process(Job job,Db db,IStore store,CancellationToken ct){if(job.Kind=="Email"){var data=System.Text.Json.JsonDocument.Parse(job.Json).RootElement;var host=config["Smtp:Host"]??throw new InvalidOperationException("SMTP is not configured");var message=new MimeMessage();message.From.Add(MailboxAddress.Parse(config["Smtp:From"]??throw new InvalidOperationException("SMTP sender missing")));message.To.Add(MailboxAddress.Parse(data.GetProperty("to").GetString()!));message.Subject=data.GetProperty("subject").GetString()??"";message.Body=new TextPart("plain"){Text=data.GetProperty("text").GetString()??""};using var client=new SmtpClient();await client.ConnectAsync(host,config.GetValue<int?>("Smtp:Port")??587,MailKit.Security.SecureSocketOptions.StartTls,ct);if(config["Smtp:Username"] is string user)await client.AuthenticateAsync(user,config["Smtp:Password"]??throw new InvalidOperationException("SMTP password missing"),ct);await client.SendAsync(message,ct);await client.DisconnectAsync(true,ct);return;}
 IOriginalDocument evidence=job.Kind.EndsWith("Report")?await db.ReportAttachments.SingleAsync(e=>e.Id==Guid.Parse(job.Json),ct):await db.Evidence.SingleAsync(e=>e.Id==Guid.Parse(job.Json),ct);var bytes=await store.Get(evidence.Key,ct);Guard.Require(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes))==evidence.Hash,"integrity","Documentul a fost modificat.","Document integrity check failed.");
 if(job.Kind is "Scan" or "ScanReport"){using var tcp=new TcpClient();await tcp.ConnectAsync(config["Scanner:Host"]??"localhost",config.GetValue<int?>("Scanner:Port")??3310,ct);await using var stream=tcp.GetStream();await stream.WriteAsync("zINSTREAM\0"u8.ToArray(),ct);for(var offset=0;offset<bytes.Length;offset+=65536){var count=Math.Min(65536,bytes.Length-offset);byte[] head=new byte[4];BinaryPrimitives.WriteInt32BigEndian(head,count);await stream.WriteAsync(head,ct);await stream.WriteAsync(bytes.AsMemory(offset,count),ct);}await stream.WriteAsync(new byte[4],ct);byte[] reply=new byte[4096];var size=await stream.ReadAsync(reply,ct);var verdict=System.Text.Encoding.UTF8.GetString(reply,0,size);if(verdict.Contains("FOUND"))evidence.Scan="Rejected";else if(verdict.Contains("OK")){evidence.Scan="Clean";if(config.GetValue<bool>("Ocr:Enabled"))db.Jobs.Add(new(){Kind=job.Kind=="ScanReport"?"OcrReport":"Ocr",Json=evidence.Id.ToString()});}else throw new IOException("Scanner returned no definitive verdict");return;}
 if(job.Kind is "Ocr" or "OcrReport"){Guard.Require(evidence.Scan=="Clean","scan","Document neverificat.","Document is not scanned.");var temp=Path.Combine(Path.GetTempPath(),"decont-"+Guid.NewGuid());Directory.CreateDirectory(temp);try{var input=Path.Combine(temp,"input"+Path.GetExtension(evidence.Name));await File.WriteAllBytesAsync(input,bytes,ct);if(evidence.Mime=="application/pdf"){await Run(config["Ocr:PdfRenderer"]??"pdftoppm",["-f","1","-singlefile","-png","-scale-to","2400",input,Path.Combine(temp,"page")],ct);input=Path.Combine(temp,"page.png");}var text=await Run(config["Ocr:Tesseract"]??"tesseract",[input,"stdout","-l",config["Ocr:Languages"]??"eng"],ct);evidence.Ocr=Serialization.Write(new{text,confidence="RequiresVerification",provider="Tesseract",state="Completed"});}finally{Directory.Delete(temp,true);}return;}throw new InvalidOperationException("Unknown job type");
 }
 static async Task<string> Run(string exe,IEnumerable<string> args,CancellationToken ct){using var process=new Process();process.StartInfo=new(exe){RedirectStandardOutput=true,RedirectStandardError=true,UseShellExecute=false};foreach(var arg in args)process.StartInfo.ArgumentList.Add(arg);process.Start();using var limit=CancellationTokenSource.CreateLinkedTokenSource(ct);limit.CancelAfter(TimeSpan.FromMinutes(3));var stdout=process.StandardOutput.ReadToEndAsync(limit.Token);var stderr=process.StandardError.ReadToEndAsync(limit.Token);try{await process.WaitForExitAsync(limit.Token);}catch{if(!process.HasExited)process.Kill(true);throw;}var error=await stderr;Guard.Require(process.ExitCode==0,"ocr","Extragerea documentului a eșuat.","Document extraction failed.");return await stdout;}
}
